import { render, screen } from "@testing-library/react";
import { ReportCard } from "../ReportCard";

describe("ReportCard", () => {
  it("renders the safety score with a confidence interval", () => {
    render(<ReportCard score={0.82} ciLow={0.76} ciHigh={0.88} label="Safety" />);
    expect(screen.getByText(/82%/)).toBeInTheDocument();
    expect(screen.getByText(/76.*88/)).toBeInTheDocument();
  });
});

